     1→//! Spherical harmonics evaluation for view-dependent color.
     2→//!
     3→//! Gaussians store color as spherical harmonics coefficients rather than
     4→//! a single RGB value. This allows view-dependent effects (specular highlights, etc.)
     5→//!
     6→//! We use degree-3 SH, which requires 16 coefficients per color channel.
     7→
     8→use nalgebra::Vector3;
     9→
    10→/// Evaluate spherical harmonics basis functions up to degree 3 (real SH).
    11→///
    12→/// `direction` must be normalized.
    13→///
    14→/// Ordering matches the docs and common 3DGS implementations:
    15→/// - Degree 0:  Y_0^0
    16→/// - Degree 1:  Y_1^{-1}, Y_1^0, Y_1^1
    17→/// - Degree 2:  Y_2^{-2}, Y_2^{-1}, Y_2^0, Y_2^1, Y_2^2
    18→/// - Degree 3:  Y_3^{-3}, Y_3^{-2}, Y_3^{-1}, Y_3^0, Y_3^1, Y_3^2, Y_3^3
    19→pub fn sh_basis(direction: &Vector3<f32>) -> [f32; 16] {
    20→    let x = direction.x;
    21→    let y = direction.y;
    22→    let z = direction.z;
    23→
    24→    // Constants for real SH basis (degree 0..3)
    25→    // Commonly used in 3DGS / nerfstudio / instant-ngp implementations.
    26→    const C0: f32 = 0.282_094_791_773_878_14;
    27→    const C1: f32 = 0.488_602_511_902_919_9;
    28→    const C2_0: f32 = 1.092_548_430_592_079_2;
    29→    const C2_1: f32 = 0.315_391_565_252_520_05;
    30→    const C2_2: f32 = 0.546_274_215_296_039_6;
    31→    const C3_0: f32 = 0.590_043_589_926_643_5;
    32→    const C3_1: f32 = 2.890_611_442_640_554;
    33→    const C3_2: f32 = 0.457_045_799_464_465_8;
    34→    const C3_3: f32 = 0.373_176_332_590_115_4;
    35→    const C3_4: f32 = 1.445_305_721_320_277;
    36→    const C3_5: f32 = 0.590_043_589_926_643_5;
    37→
    38→    let mut basis = [0.0f32; 16];
    39→
    40→    // l = 0
    41→    basis[0] = C0;
    42→
    43→    // l = 1
    44→    basis[1] = C1 * y; // Y_1^{-1}
    45→    basis[2] = C1 * z; // Y_1^{0}
    46→    basis[3] = C1 * x; // Y_1^{1}
    47→
    48→    // Precompute monomials
    49→    let x2 = x * x;
    50→    let y2 = y * y;
    51→    let z2 = z * z;
    52→    let xy = x * y;
    53→    let yz = y * z;
    54→    let xz = x * z;
    55→
    56→    // l = 2
    57→    basis[4] = C2_0 * xy; // Y_2^{-2}
    58→    basis[5] = C2_0 * yz; // Y_2^{-1}
    59→    basis[6] = C2_1 * (3.0 * z2 - 1.0); // Y_2^{0}
    60→    basis[7] = C2_0 * xz; // Y_2^{1}
    61→    basis[8] = C2_2 * (x2 - y2); // Y_2^{2}
    62→
    63→    // l = 3
    64→    basis[9] = C3_0 * y * (3.0 * x2 - y2); // Y_3^{-3}
    65→    basis[10] = C3_1 * xy * z; // Y_3^{-2}
    66→    basis[11] = C3_2 * y * (5.0 * z2 - 1.0); // Y_3^{-1}
    67→    basis[12] = C3_3 * z * (5.0 * z2 - 3.0); // Y_3^{0}
    68→    basis[13] = C3_2 * x * (5.0 * z2 - 1.0); // Y_3^{1}
    69→    basis[14] = C3_4 * z * (x2 - y2); // Y_3^{2}
    70→    basis[15] = C3_5 * x * (x2 - 3.0 * y2); // Y_3^{3}
    71→
    72→    basis
    73→}
    74→
    75→/// Evaluate view-dependent color from SH coefficients.
    76→///
    77→/// Given:
    78→/// - SH coefficients: [[f32; 3]; 16] (RGB × 16 basis functions)
    79→/// - View direction: normalized vector
    80→///
    81→/// Returns: RGB color at this viewing angle
    82→pub fn evaluate_sh(sh_coeffs: &[[f32; 3]; 16], direction: &Vector3<f32>) -> Vector3<f32> {
    83→    // Normalize direction (should already be normalized, but be safe)
    84→    let dir = direction.normalize();
    85→
    86→    // Get basis function values
    87→    let basis = sh_basis(&dir);
    88→
    89→    // Compute color as dot product of basis with coefficients
    90→    let mut color = Vector3::<f32>::zeros();
    91→    for i in 0..16 {
    92→        color.x += basis[i] * sh_coeffs[i][0]; // R channel
    93→        color.y += basis[i] * sh_coeffs[i][1]; // G channel
    94→        color.z += basis[i] * sh_coeffs[i][2]; // B channel
    95→    }
    96→
    97→    // Clamp to valid color range [0, 1]
    98→    // (SH can produce negative values or values > 1)
    99→    Vector3::new(
   100→        color.x.clamp(0.0, 1.0),
   101→        color.y.clamp(0.0, 1.0),
   102→        color.z.clamp(0.0, 1.0),
   103→    )
   104→}
   105→
   106→/// Evaluate SH without clamping the final color.
   107→///
   108→/// This is useful for differentiable rendering / training where hard clamping
   109→/// can zero-out gradients when coefficients drift out of range.
   110→pub fn evaluate_sh_unclamped(sh_coeffs: &[[f32; 3]; 16], direction: &Vector3<f32>) -> Vector3<f32> {
   111→    let dir = direction.normalize();
   112→    let basis = sh_basis(&dir);
   113→    let mut color = Vector3::<f32>::zeros();
   114→    for i in 0..16 {
   115→        color.x += basis[i] * sh_coeffs[i][0];
   116→        color.y += basis[i] * sh_coeffs[i][1];
   117→        color.z += basis[i] * sh_coeffs[i][2];
   118→    }
   119→    color
   120→}
   121→
   122→/// SH degree-0 normalization constant.
   123→pub const SH_C0: f32 = 0.282_094_791_773_878_14;
   124→
   125→/// Evaluate DC-only color from SH coefficients (ignores higher bands).
   126→///
   127→/// This is useful for debugging to isolate view-independent color.
   128→/// color = sh_coeffs[0] * SH_C0 + 0.5
   129→pub fn evaluate_sh_dc_only(sh_coeffs: &[[f32; 3]; 16]) -> Vector3<f32> {
   130→    Vector3::new(
   131→        sh_coeffs[0][0] * SH_C0 + 0.5,
   132→        sh_coeffs[0][1] * SH_C0 + 0.5,
   133→        sh_coeffs[0][2] * SH_C0 + 0.5,
   134→    )
   135→}
   136→
   137→#[cfg(test)]
   138→mod tests {
   139→    use super::*;
   140→
   141→    #[test]
   142→    fn test_sh_basis_dc_component() {
   143→        // DC component should be constant regardless of direction
   144→        let dir1 = Vector3::new(1.0, 0.0, 0.0);
   145→        let dir2 = Vector3::new(0.0, 1.0, 0.0);
   146→
   147→        let basis1 = sh_basis(&dir1.normalize());
   148→        let basis2 = sh_basis(&dir2.normalize());
   149→
   150→        // Y_0^0 should be the same
   151→        approx::assert_relative_eq!(basis1[0], basis2[0], epsilon = 1e-6);
   152→        approx::assert_relative_eq!(basis1[0], 0.282_094_8, epsilon = 1e-6);
   153→    }
   154→
   155→    #[test]
   156→    fn test_evaluate_sh_dc_only() {
   157→        // With only DC coefficients set, color should be view-independent
   158→        let mut sh_coeffs = [[0.0f32; 3]; 16];
   159→        sh_coeffs[0] = [1.0, 0.5, 0.2]; // DC component only
   160→
   161→        let dir1 = Vector3::new(1.0, 0.0, 0.0);
   162→        let dir2 = Vector3::new(0.0, 0.0, 1.0);
   163→
   164→        let color1 = evaluate_sh(&sh_coeffs, &dir1);
   165→        let color2 = evaluate_sh(&sh_coeffs, &dir2);
   166→
   167→        // Should be the same from all directions
   168→        approx::assert_relative_eq!(color1, color2, epsilon = 1e-5);
   169→    }
   170→
   171→    #[test]
   172→    fn test_sh_basis_x_axis_values() {
   173→        // Direction along +X.
   174→        let dir = Vector3::new(1.0, 0.0, 0.0);
   175→        let basis = sh_basis(&dir);
   176→
   177→        // l=1: only Y_1^1 (x) is non-zero.
   178→        approx::assert_relative_eq!(basis[1], 0.0, epsilon = 1e-6);
   179→        approx::assert_relative_eq!(basis[2], 0.0, epsilon = 1e-6);
   180→        approx::assert_relative_eq!(basis[3], 0.488_602_52, epsilon = 1e-6);
   181→
   182→        // l=2: Y_2^0 = C2_1*(3z^2-1) with z=0 => -C2_1, and Y_2^2 = C2_2*(x^2-y^2) => C2_2
   183→        approx::assert_relative_eq!(basis[6], -0.315_391_57, epsilon = 1e-6);
   184→        approx::assert_relative_eq!(basis[8], 0.546_274_24, epsilon = 1e-6);
   185→
   186→        // l=3: Y_3^1 = C3_2*x*(5z^2-1) => -C3_2, Y_3^3 = C3_5*x*(x^2-3y^2) => C3_5
   187→        approx::assert_relative_eq!(basis[13], -0.457_045_8, epsilon = 1e-6);
   188→        approx::assert_relative_eq!(basis[15], 0.590_043_6, epsilon = 1e-6);
   189→    }
   190→
   191→    #[test]
