   928→    /// Verify rotation matrix is orthonormal
   929→    pub fn verify_rotation_orthonormal(rotation: &Matrix3<f32>, tolerance: f32) -> bool {
   930→        let rt_r: Matrix3<f32> = rotation.transpose() * rotation;
   931→        let identity: Matrix3<f32> = Matrix3::identity();
