   946→    /// Compute rotation error in degrees between two rotation matrices
   947→    pub fn rotation_error_degrees(r1: &Matrix3<f32>, r2: &Matrix3<f32>) -> f32 {
   948→        // Error rotation: R_error = R1^T * R2
   949→        let r_error = r1.transpose() * r2;
   950→
   951→        // Extract angle from rotation matrix using trace
   952→        // trace(R) = 1 + 2*cos(theta)
   953→        let trace = r_error[(0, 0)] + r_error[(1, 1)] + r_error[(2, 2)];
