        let rotation = UnitQuaternion::from_euler_angles(
            30.0f32.to_radians(),
            45.0f32.to_radians(),
            60.0f32.to_radians(),
        );

        let gaussian = Gaussian::new(
            Vector3::zeros(),
            log_scale,
            rotation,
            0.0,
            [[0.0; 3]; 16],
        );

